// BackstopJS config for the oracle comparison. Scenarios are
// generated by ../run-backstop.mjs into scenarios.json: the targeted mutant
// catalog plus benign-change and equivalent probes. Everything else stays at
// Backstop defaults, in particular the 0.1% misMatchThreshold.
//
// The survivor cross-check (--survivors) points LL_BS_SCENARIOS/LL_BS_DATA at
// its own scenario list and data directory, so the main comparison's
// artifacts stay in place.
const scenarios = require(process.env.LL_BS_SCENARIOS ?? "./scenarios.json");
const dataDir = __dirname + "/" + (process.env.LL_BS_DATA ?? "data");

module.exports = {
  id: "layout_lint_eval",
  viewports: [{ label: "study", width: 1280, height: 900 }],
  scenarios,
  paths: {
    bitmaps_reference: dataDir + "/bitmaps_reference",
    bitmaps_test: dataDir + "/bitmaps_test",
    engine_scripts: __dirname,
    html_report: dataDir + "/html_report",
    json_report: dataDir + "/json_report",
  },
  report: ["json"],
  engine: "puppeteer",
  engineOptions: { args: ["--no-sandbox"] },
  asyncCaptureLimit: 5,
  asyncCompareLimit: 20,
};
